        val wm = agent.snapshotWorkingMemory()
        if (wm.goal.isNullOrBlank() && wm.keyFacts.isEmpty() && wm.openQuestions.isEmpty()) {
            return "Рабочая память пуста"
        }

        return buildString {
            appendLine("Цель: ${wm.goal ?: "—"}")
